package main

import (
	"fmt"
	"regexp"
)

func main() {
	emailContent := "From:Alex <alex@example.com>\nPlease unsubscribe me from this mailing list."
	email := extractEmail(emailContent)
	fmt.Println("Extracted Email:", email)
}

func extractEmail(content string) string {
	re := regexp.MustCompile(`From:\s*([^<]+<([^>]+)>)`)
	matches := re.FindStringSubmatch(content)
	if len(matches) > 2 {
		return matches[2]
	}
	return ""
}

emailContent := "Please unsubscribe me from this mailing list."
keywords := []string{"unsubscribe", "remove me", "deregister me", "stop sending me", "delete me"}
for _, keyword := range keywords {
    if strings.Contains(strings.ToLower(emailContent), keyword) {
        fmt.Println("Unsubscribe request detected.")
        break
    }
}
